button.clickEventHandler:
var callback = function callback() {
  ESS.actions.facilityActions.runFacility({id:'4ad03918-61bb-4c31-8e27-4926b7c60401'}, {parameters:{AssignmentId: data.id, PerformerId: data.performer, AssignmentType: data.name}});
  ESS.closeElement(sender)
};

var documents = data.attachments.filter(x => x.group === 'DocumentGroup').map(a => ({ id: a.id, title: a.title }));
if (documents !== undefined && documents.length != 0) {
  ESS.scripts.HRProVacations.signFromObjectCard({ data, documents, callback });
} else {
  callback();
}

var callback = function callback() {
  ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Confirm').then(function () {
    ESS.closeElement(sender);
    ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.OBJECTCARD_VACATIONCONFIRMATIONASSIGNMENTOBJECTCARD_FACILITY_SUCCESSMESSAGE'), 'success', true);
    ESS.widgets.updateWidgets();
  }).catch(function (error) {
    ESS.toasts.showErrorToastWithLog(ESS.L('@HRPROVACATIONS.ERROR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
  });
};

var documents = data.attachments.filter(x => x.group === 'DocumentGroup').map(a => ({ id: a.id, title: a.title }));
if (documents !== undefined && documents.length != 0) {
  ESS.scripts.HRProVacations.signFromObjectCard({ data, documents, callback });
} else {
  callback();
}

objectCard.openedEventHandler:
var assignmentId = data.id;
ESS.network.sendRequest(`/api/functions/GetAssignmentInstructionForEss?assignmentId=${assignmentId}`)
.then(function (instruction) {
  if (instruction)
    configuration.content = ESS.L('@HRPROVACATIONS.COMMON_INSTRUCTION') + '<br/><br/>' + instruction;
  resolve({configuration: configuration, data: data});
})
.catch(function (error) {
  ESS.toasts.showToast(error.message, 'danger', false);
  reject();
});
